<?php $esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}; ?><!doctype html><html><head><meta charset="utf-8"><?php include('includes/page-title.php'); ?><link href="<?=base_url()?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?=base_url()?>assets/css/icons.min.css" rel="stylesheet"><link href="<?=base_url()?>assets/css/app.min.css" rel="stylesheet"><style>body{background:#f4f6fb}.hero{margin:20px 0;padding:28px;border-radius:18px;color:#fff;background:linear-gradient(135deg,#1c6e8c,#4dbd74)}.hero h2{color:#fff}.card{border:0;box-shadow:0 4px 15px #0001}</style></head><body><div id="wrapper"><?php include('includes/top-bar.php');include('includes/sidebar.php');?><div class="content-page"><div class="content"><div class="container-fluid"><div class="hero d-flex justify-content-between align-items-center"><div><small>QMS · RISK MANAGEMENT</small><h2>Opportunity Registry</h2><span><?= $esc($sectionName);?></span></div><div><a class="btn btn-light" target="_blank" href="<?=base_url()?>Page/opportunity_registry_report">Generate Report</a> <a class="btn btn-outline-light" href="<?=base_url()?>Page/opportunity_registry_add">Add Opportunity</a></div></div><?php if($this->session->flashdata('success')):?><div class="alert alert-success"><?= $esc($this->session->flashdata('success'));?></div><?php endif;?><?php if($this->session->flashdata('danger')):?><div class="alert alert-danger"><?= $esc($this->session->flashdata('danger'));?></div><?php endif;?><div class="card"><div class="card-body table-responsive"><table class="table table-hover"><thead><tr><th>#</th><th>Declared Process &amp; Opportunity</th><th>Rating</th><th>Pursuit Action Plan</th><th>Responsible</th><th>Target Date</th><th></th></tr></thead><tbody><?php if(empty($entries)):?><tr><td colspan="7" class="text-center text-muted">No opportunities entered yet.</td></tr><?php else:foreach($entries as $i=>$e):?><tr><td><?= $i+1;?></td><td><?=nl2br($esc($e->declared_process_opportuni